"""Seed only the fresh directory generated by the browser QA fixture."""
import os
from pathlib import Path
import sys

root = Path(os.environ['TRAVEL_DATA_DIR'])
assert root.is_absolute() and root.parent.name.startswith('travel-browser-accounts-')
assert not (root/'app.db').exists(), 'Refuse to seed an existing database'
assert not os.environ.get('AMAP_API_KEY') and not os.environ.get('ZHIPU_API_KEY')
sys.path.insert(0,str(Path.cwd()))
from app.db.database import init_db, SessionLocal
from app.db.models import Spot
init_db()
with SessionLocal() as db:
    # The empty POI id verifies retry protection without POI-based deduplication.
    db.add_all([Spot(name='隔离景点一',city='杭州',amap_id='',address='合成地址一',source='隔离验收'),
                Spot(name='隔离景点二',city='杭州',amap_id='QA-SECOND',address='合成地址二',source='隔离验收')])
    db.commit()
import uvicorn
uvicorn.run('app.main:app',host='127.0.0.1',port=18963,log_level='warning')
